import argparse
def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {}
    remaining_arguments = unparsed_arguments.copy()

    for name, subparser in subparsers.items():
        try:
            # Attempt to parse the arguments for this subparser
            parsed_namespace = subparser.parse_known_args(remaining_arguments)[0]
            parsed_arguments[name] = parsed_namespace
            # Remove the arguments that were successfully parsed
            remaining_arguments = [arg for arg in remaining_arguments if arg not in parsed_namespace._get_kwargs()]
        except SystemExit:
            continue  # If parsing fails, just continue to the next subparser

    return parsed_arguments, remaining_arguments

