class DigestChecker:
    def __init__(self):
        self.errors = []

    def error(self, message):
        self.errors.append(message)

    def check_digests_present_and_used(self, manifest_files, digests_used):
        all_digests = set()
        for manifest_file in manifest_files:
            with open(manifest_file, 'r') as file:
                for line in file:
                    digest = self.extract_digest(line)
                    if digest:
                        all_digests.add(digest)

        missing_digests = set(digests_used) - all_digests
        if missing_digests:
            self.error(f"Missing digests: {', '.join(missing_digests)}")

        unused_digests = all_digests - set(digests_used)
        if unused_digests:
            self.error(f"Unused digests: {', '.join(unused_digests)}")

    def extract_digest(self, line):
        # Assuming the digest is the first word in the line
        parts = line.split()
        return parts[0] if parts else None

