import hashlib

class VersionValidator:
    def __init__(self):
        self.digest_mismatches = []

    def calculate_digest(self, file_path):
        hash_md5 = hashlib.md5()
        with open(file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_md5.update(chunk)
        return hash_md5.hexdigest()

    def validate_version_inventories(self, version_dirs):
        root_inventory_path = 'root_inventory.txt'
        root_digests = self._read_inventory(root_inventory_path)

        for version_dir in version_dirs:
            version_inventory_path = os.path.join(version_dir, 'inventory.txt')
            if not os.path.exists(version_inventory_path):
                print(f"Missing inventory for version {version_dir}")
                continue

            version_digests = self._read_inventory(version_inventory_path)
            self._compare_digests(root_digests, version_digests, version_dir)

    def _read_inventory(self, inventory_path):
        digests = {}
        if os.path.exists(inventory_path):
            with open(inventory_path, 'r') as f:
                for line in f:
                    parts = line.strip().split()
                    if len(parts) == 2:
                        file_path, digest = parts
                        digests[file_path] = digest
        return digests

    def _compare_digests(self, root_digests, version_digests, version_dir):
        for file_path, root_digest in root_digests.items():
            version_digest = version_digests.get(file_path)
            if version_digest and version_digest!= root_digest:
                self.digest_mismatches.append((version_dir, file_path, root_digest, version_digest))
                print(f"Digest mismatch in {version_dir} for {file_path}: {root_digest}!= {version_digest}")

def next_version(version):
    major, minor, patch = map(int, version.split('.'))
    patch += 1
    if patch == 10:
        patch = 0
        minor += 1
        if minor == 10:
            minor = 0
            major += 1
    return f"{major}.{minor}.{patch}"

