def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field, schema_info in observer_schema.items():
        if field in response:
            if field not in last_applied_manifest:
                last_applied_manifest[field] = {}

            if 'fields' in schema_info:
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field], schema_info['fields'], response[field]
                )
            else:
                last_applied_manifest[field] = response[field]
        else:
            raise KeyError(f"Observed field {field} is not present in the Kubernetes response")

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for i, field in enumerate(observer_schema):
        if isinstance(field, dict):
            key = list(field.keys())[0]
            if key not in last_applied_manifest:
                last_applied_manifest.append({})
            if key not in last_applied_manifest[i]:
                last_applied_manifest[i][key] = {}
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[i][key].values(),
                field[key],
                response[i][key].values()
            )
        elif isinstance(field, list):
            if len(field) > 0:
                key = list(field[0].keys())[0]
                if key not in last_applied_manifest[i]:
                    last_applied_manifest[i][key] = []
                if len(last_applied_manifest[i][key]) < len(response[i][key]):
                    last_applied_manifest[i][key].append({})
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[i][key],
                    field,
                    response[i][key]
                )
        else:
            if field not in last_applied_manifest[i]:
                last_applied_manifest[i][field] = response[i][field]

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    schema_dict = {}

    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            schema_dict[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            if value and isinstance(value[0], dict):
                schema_dict[key] = [generate_default_observer_schema_dict(value[0])]
            else:
                schema_dict[key] = []
        else:
            schema_dict[key] = type(value).__name__

    if first_level:
        return {k: 'object' if isinstance(v, dict) else 'array' if isinstance(v, list) else type(v).__name__ for k, v in schema_dict.items()}

    return schema_dict

