class Histogram:
    def __init__(self, min_edge, max_edge, bins):
        self.min_edge = min_edge
        self.max_edge = max_edge
        self.bins = bins
        self.bin_width = (max_edge - min_edge) / bins
        self.histogram = [0.0] * bins

    def fill(self, coord, weight=1):
        if self.min_edge <= coord < self.max_edge:
            index = int((coord - self.min_edge) / self.bin_width)
            self.histogram[index] += weight

    def get_histogram(self):
        return self.histogram

def difference(d1, d2, level=-1):
    def items_not_in(d1, d2):
        return {k: v for k, v in d1.items() if k not in d2}

    def recursive_difference(d1, d2, level):
        if level == 0:
            return items_not_in(d1, d2)

        diff = items_not_in(d1, d2)
        for k, v in d1.items():
            if isinstance(v, dict) and k in d2 and isinstance(d2[k], dict):
                nested_diff = recursive_difference(v, d2[k], level - 1)
                if nested_diff:
                    diff[k] = nested_diff

        return diff

    return recursive_difference(d1, d2, level)

