class Histogram:
    def __init__(self, data):
        self.data = data
        self._scale = None

    def _compute_scale(self):
        return sum(self.data)

    def scale(self, other=None, recompute=False):
        if other is None:
            if self._scale is None or recompute:
                self._scale = self._compute_scale()
            return self._scale

        if not isinstance(other, (float, int)):
            raise LenaValueError("Provided scale must be a float or int.")

        current_scale = self.scale(recompute=recompute)
        if current_scale == 0:
            raise LenaValueError("Cannot rescale histogram with scale equal to zero.")

        factor = other / current_scale
        self.data = [x * factor for x in self.data]
        self._scale = other

