        self._scale = scale
        self._fields = fields if fields else {}

    def scale(self, other=None):
        if other is None:
            return self._scale

        if self._scale is None or self._scale == 0:
            raise LenaValueError("Cannot rescale a graph with unknown or zero scale.")

        last_field = next(reversed(self._fields), None)
        if last_field is None:
            raise LenaValueError("Graph has no fields to rescale.")

        scale_factor = other / self._scale
        for field, coordinates in self._fields.items():
            for i, coord in enumerate(coordinates):
                if field == last_field:
                    coordinates[i] = coord * scale_factor

        self._scale = other

