class TimezoneConverter:
    def __init__(self, offset_hours, name):
        self.offset = timedelta(hours=offset_hours)
        self.name = name

    def _fromutc(self, dt):
        if dt.tzinfo is None or dt.tzinfo.utcoffset(dt) is None:
            raise ValueError("The input datetime must be timezone-aware")

        utc_time = dt.astimezone(timezone.utc)
        local_time = utc_time + self.offset
        return local_time.replace(tzinfo=timezone(self.offset)).astimezone(self.offset)

