from zope.interface import Interface, implementer, providedBy, Invalid
def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    def check_provided_by():
        if not tentative and not iface.providedBy(candidate):
            errors.append(
                f"{candidate} does not provide {iface}"
            )

    def check_methods():
        missing_methods = [method for method in iface.names() if not hasattr(candidate, method)]
        if missing_methods:
            errors.append(
                f"Missing methods: {', '.join(missing_methods)}"
            )

    def check_method_signatures():
        for method_name in iface.names():
            if hasattr(candidate, method_name):
                candidate_method = getattr(candidate, method_name)
                iface_method = getattr(iface, method_name, None)
                if iface_method and callable(iface_method):
                    if getattr(candidate_method, '__code__', None)!= getattr(iface_method, '__code__', None):
                        errors.append(
                            f"Method {method_name} signature mismatch in {candidate}"
                        )

    def check_attributes():
        missing_attributes = [attr for attr in iface.names() if not hasattr(candidate, attr)]
        if missing_attributes:
            errors.append(
                f"Missing attributes: {', '.join(missing_attributes)}"
            )

    check_provided_by()
    check_methods()
    check_method_signatures()
    check_attributes()

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        raise Invalid("\n".join(errors))

    return True

