from inspect import signature, Signature, Parameter
def verifyObject(iface, candidate, tentative=False):
    if not tentative and not iface.providedBy(candidate):
        raise Invalid(f"{candidate} does not provide {iface}")

    errors = []

    # Check methods
    for method_name, method in iface.namesAndDescriptions(1):
        if method_name not in candidate.__dict__:
            errors.append(f"Missing method: {method_name}")
            continue

        candidate_method = getattr(candidate, method_name)
        expected_signature = signature(method)
        actual_signature = signature(candidate_method)

        if expected_signature!= actual_signature:
            errors.append(
                f"Method {method_name} signature mismatch: "
                f"expected {expected_signature}, got {actual_signature}"
            )

    # Check attributes
    for attr_name, _ in iface.namesAndDescriptions(2):
        if not hasattr(candidate, attr_name):
            errors.append(f"Missing attribute: {attr_name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("Errors:\n" + "\n".join(errors))

    return True

