def determineMetaclass(bases, explicit_mc=None):
    if explicit_mc is not None:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        if hasattr(base, '__metaclass__'):
            metaclasses.add(base.__metaclass__)
        else:
            metaclasses.update(getattr(base, '__mro__', ()))

    if len(metaclasses) == 1:
        return metaclasses.pop()

    if len(metaclasses) > 1:
        metaclasses.discard(type)
        if len(metaclasses) == 1:
            return metaclasses.pop()
        raise TypeError("Cannot create a consistent method resolution "
                        "order (MRO) for bases {}.".format(bases))

    return type

def minimalBases(classes):
    subclasses_map = {}

    for cls in classes:
        base = cls.__bases__
        for b in base:
            if b in subclasses_map:
                subclasses_map[b].add(cls)
            else:
                subclasses_map[b] = {cls}

    all_classes = set(classes)
    minimal_bases = all_classes.copy()

    for subclasses in subclasses_map.values():
        minimal_bases -= subclasses

    return list(minimal_bases)

