class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.min_freq = 0
        self.key_to_val = {}
        self.key_to_freq = {}
        self.freq_to_keys = {}

    def popitem(self):
        if not self.key_to_val:
            return None

        # Get the keys with the least frequency
        keys = self.freq_to_keys.get(self.min_freq, [])
        if not keys:
            return None

        # Pop the least frequently used key
        key_to_remove = keys.pop(0)

        # If no keys left for this frequency, clean up the frequency list
        if not keys:
            del self.freq_to_keys[self.min_freq]

        # Remove the key from other structures
        value = self.key_to_val.pop(key_to_remove)
        freq = self.key_to_freq.pop(key_to_remove)

        # Update the frequency list
        self.freq_to_keys[freq].remove(key_to_remove)

        # Update the minimum frequency if needed
        if not self.freq_to_keys.get(self.min_freq):
            self.min_freq += 1

        return (key_to_remove, value)

    def get(self, key: int):
        if key not in self.key_to_val:
            return -1
        self._update_freq(key)
        return self.key_to_val[key]

    def put(self, key: int, value: int):
        if self.capacity <= 0:
            return

        if key in self.key_to_val:
            self.key_to_val[key] = value
            self._update_freq(key)
        else:
            if len(self.key_to_val) >= self.capacity:
                self.popitem()
            self.key_to_val[key] = value
            self.key_to_freq[key] = 1
            self.freq_to_keys.setdefault(1, []).append(key)
            self.min_freq = 1

    def _update_freq(self, key: int):
        freq = self.key_to_freq[key]
        keys = self.freq_to_keys[freq]
        keys.remove(key)

        if not keys:
            del self.freq_to_keys[freq]
            if self.min_freq == freq:
                self.min_freq += 1

        self.key_to_freq[key] += 1
        new_freq = self.key_to_freq[key]
        self.freq_to_keys.setdefault(new_freq, []).append(key)

