from threading import Lock
def cached(cache, key=None, lock=None):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal key
            if key is None:
                key = lambda *a, **kw: hash((a, tuple(sorted(kw.items()))))
            cache_key = key(*args, **kwargs)

            if lock:
                with lock:
                    result = cache.get(cache_key)
                    if result is None:
                        result = func(*args, **kwargs)
                        cache[cache_key] = result
            else:
                result = cache.get(cache_key)
                if result is None:
                    result = func(*args, **kwargs)
                    cache[cache_key] = result
            return result
        return wrapper
    return decorator

