from typing import Sequence, Tuple
def _get_platform_max_length() -> int:
    return 255  # Typical max length for a command line on many platforms
def _execute_command(command: Tuple[str,...], color: bool):
    if color:
        print(f"\033[94mExecuting: {' '.join(command)}\033[0m")
    else:
        print(f"Executing: {' '.join(command)}")
    subprocess.run(command)
def xargs(
    cmd: Tuple[str,...],
    varargs: Sequence[str],
    *,
    color: bool = False,
    target_concurrency: int = 1,
    _max_length: int = _get_platform_max_length(),
    **kwargs
):
    def build_command(args_chunk: Sequence[str]):
        return (*cmd, *args_chunk)

    def chunk_args(args, max_length):
        chunk = []
        current_length = len(' '.join(cmd)) + 1  # +1 for the space between cmd and first arg
        for arg in args:
            if current_length + len(arg) + 1 > max_length:
                yield chunk
                chunk = []
                current_length = len(' '.join(cmd)) + 1
            chunk.append(arg)
            current_length += len(arg) + 1
        if chunk:
            yield chunk

    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        for chunk in chunk_args(varargs, _max_length):
            executor.submit(_execute_command, build_command(chunk), color)

