class Time:
    @classmethod
    def from_ticks(cls, ticks, tz=None):
        if not (0 <= ticks < 86400000000000):
            raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")

        seconds, nanoseconds = divmod(ticks, 1_000_000_000)
        time_of_day = timedelta(seconds=seconds, microseconds=nanoseconds // 1000)

        naive_time = datetime.combine(datetime.today(), datetime.min.time()) + time_of_day
        if tz:
            return naive_time.replace(tzinfo=tz)
        return naive_time.time()

