from datetime import datetime, timezone, timedelta
def hydrate_time(nanoseconds, tz=None):
    seconds, nanoseconds = divmod(nanoseconds, 1_000_000_000)
    dt = datetime.fromtimestamp(seconds, tz)
    dt = dt.replace(microsecond=nanoseconds // 1_000)

    if tz is None:
        return dt.isoformat()
    elif isinstance(tz, str):
        tz_info = timezone(timedelta(seconds=int(tz)))
        dt = dt.replace(tzinfo=tz_info)
        return dt.isoformat()
    elif isinstance(tz, (timezone, timedelta)):
        dt = dt.replace(tzinfo=tz)
        return dt.isoformat()
    else:
        raise ValueError("Invalid timezone format")

