import importlib.util
import sys
def subprocess_run_helper(func_module_name, func_name, *args, timeout, extra_env=None):
    def worker(q, module_name, function_name, func_args):
        try:
            spec = importlib.util.find_spec(module_name)
            if spec is None:
                raise ImportError(f"Module {module_name} not found")
            module = importlib.util.module_from_spec(spec)
            sys.modules[module_name] = module
            spec.loader.exec_module(module)
            func = getattr(module, function_name)
            result = func(*func_args)
            q.put(subprocess.CompletedProcess(args=func_args, returncode=0, stdout=result, stderr=None))
        except Exception as e:
            q.put(subprocess.CompletedProcess(args=func_args, returncode=1, stdout=None, stderr=str(e)))

    if extra_env is None:
        extra_env = {}

    q = multiprocessing.Queue()
    p = multiprocessing.Process(target=worker, args=(q, func_module_name, func_name, args))
    p.start()
    p.join(timeout)

    if p.is_alive():
        p.terminate()
        p.join()
        return subprocess.CompletedProcess(args=args, returncode=-1, stdout=None, stderr="Timeout")

    return q.get()

