    missing_args = required_args - args.keys()

    if missing_args:
        raise ValueError(f"Missing required arguments: {', '.join(missing_args)}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    required_args = []
    for option in options_spec:
        required_when = option.get('required_when')
        if required_when:
            condition, arg_name = required_when.split(':')
            if condition in args and args[condition] == 'true':
                required_args.append(arg_name)
    return required_args

def validate_length_args(self, args, max_lengths):
    for arg_name, arg_value in args.items():
        if arg_name in max_lengths and isinstance(arg_value, str):
            if len(arg_value) > max_lengths[arg_name]:
                raise ValueError(f"Argument '{arg_name}' exceeds maximum length of {max_lengths[arg_name]}")

def validate_choices_args(self, args):
    choices = {
        'option1': ['value1', 'value2', 'value3'],
        'option2': ['value4', 'value5'],
        'option3': ['value6', 'value7', 'value8', 'value9'],
    }

    for key, value in args.items():
        if key in choices:
            if value not in choices[key]:
                raise ValueError(f"Invalid value '{value}' for argument '{key}'. Expected one of {choices[key]}.")

class Validator:
    def __init__(self, min_values, max_values):
        self.min_values = min_values
        self.max_values = max_values

    def validate_min_max_args(self, args):
        if len(args)!= len(self.min_values) or len(args)!= len(self.max_values):
            raise ValueError("Argument count does not match min or max values count.")

        for i, value in enumerate(args):
            if not (self.min_values[i] <= value <= self.max_values[i]):
                raise ValueError(f"Argument at index {i} is out of bounds: {value}")

