def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}

    for arg in args:
        key, value = arg.split('=', 1)

        if key.startswith('--control-'):
            control_args[key[10:]] = value
        elif key.startswith('--nested-'):
            nested_args[key[9:]] = value
        elif key.startswith('--custom-'):
            nested_args[key[9:]] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars is None:
        extra_vars = {}

    for key, value in extra_vars.items():
        if key in vars_dict and isinstance(vars_dict[key], dict) and isinstance(value, dict):
            merge_extra_vars(vars_dict[key], value)
        else:
            vars_dict[key] = value

import subprocess
import shlex
def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    cmd = ["ansible-playbook", playbook_path]

    if verbose is not None:
        cmd.extend(["-v"] * verbose)

    if extra_vars:
        extra_vars_str = " ".join(f"{key}={value}" for key, value in extra_vars.items())
        cmd.extend(["-e", extra_vars_str])

    if ansible_args:
        for arg, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    cmd.append(f"--{arg}")
            else:
                cmd.extend([f"--{arg}", str(value)])

    result = subprocess.run(cmd, capture_output=True, text=True)
    return result.stdout, result.stderr

def _convert_non_cli_args(self, parser_name, values_dict):
    conversion_map = {
       'main': {
            'timeout': int,
           'verbose': bool,
        },
        'virsh': {
           'memory': int,
            'cpu': int,
        },
        'ospd': {
            'port': int,
            'debug': bool,
        }
    }

    if parser_name in conversion_map:
        for key, conversion_func in conversion_map[parser_name].items():
            if key in values_dict:
                try:
                    values_dict[key] = conversion_func(values_dict[key])
                except (ValueError, TypeError):
                    pass

import os
import yaml
def get_plugin_spec_flatten_dict(plugin_dir):
    def load_yaml_file(file_path):
        with open(file_path, 'r') as file:
            return yaml.safe_load(file) or {}

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    plugin_spec = {}
    for root, _, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith('.yaml') or file.endswith('.yml'):
                file_path = os.path.join(root, file)
                yaml_data = load_yaml_file(file_path)
                flattened_data = flatten_dict(yaml_data)
                plugin_spec.update(flattened_data)

    return plugin_spec

