from datetime import datetime
from pytz import timezone
def ensure_timezone(dt, tz_name='UTC'):
    tz = timezone(tz_name)
    return dt.astimezone(tz) if dt.tzinfo else tz.localize(dt)
def format_dt(dt):
    dt = ensure_timezone(dt)
    return dt.strftime('%Y-%m-%d %H:%M:%S %Z%z')

from typing import Callable, Set, Tuple
def find_tags(text: str, replacer: Callable[[str], str] = None) -> Tuple[Set[str], str]:
    in_code_block = False
    tags = set()
    result_text = []
    word = ""

    for char in text:
        if char == '`':
            in_code_block = not in_code_block
            if word:
                result_text.append(word)
                word = ""
            result_text.append(char)
        elif char.isspace() or char in {',', '.', '!', '?', ';', ':', '-', '(', ')', '[', ']', '{', '}', '"', '\''}:
            if not in_code_block and word.isalpha():
                tags.add(word)
                if replacer:
                    word = replacer(word)
            result_text.append(word)
            result_text.append(char)
            word = ""
        else:
            word += char

    if word:
        result_text.append(word)

    return tags, ''.join(result_text)

import re
from urllib.parse import urlparse
def process_text_links(text):
    def is_valid_url(url):
        try:
            result = urlparse(url)
            return all([result.scheme, result.netloc])
        except ValueError:
            return False

    def linkify(match):
        url = match.group(0)
        if is_valid_url(url):
            return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'
        return url

    url_pattern = r'https?://[^\s]+'
    processed_text = re.sub(url_pattern, linkify, text)

    return processed_text

from typing import Optional
import requests
def fetch_content_type(url: str) -> Optional[str]:
    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/58.0.3029.110 Safari/537.3'
    }
    try:
        response = requests.head(url, headers=headers)
        response.raise_for_status()
        return response.headers.get('Content-Type')
    except requests.RequestException:
        return None

