def xml_children_as_dict(node):
    children_dict = {}
    for child in node:
        tag = child.tag
        if tag in children_dict:
            if isinstance(children_dict[tag], list):
                children_dict[tag].append(child)
            else:
                children_dict[tag] = [children_dict[tag], child]
        else:
            children_dict[tag] = child
    return children_dict

import requests
def get_nodeinfo_well_known_document(url, document_path=None):
    if not document_path:
        document_path = '/.well-known/nodeinfo'
    try:
        response = requests.get(f"{url}{document_path}")
        response.raise_for_status()
        return {
            'url': url,
            'document_path': document_path,
           'status_code': response.status_code,
            'content': response.json() if response.headers.get('Content-Type') == 'application/json' else response.text
        }
    except requests.RequestException:
        return {
            'url': url,
            'document_path': document_path,
           'status_code': None,
            'content': None
        }

