import requests
from xml.etree import ElementTree as ET
class XRD:
    def __init__(self, root):
        self.root = root

    def __repr__(self):
        return ET.tostring(self.root, encoding='unicode')
def retrieve_diaspora_host_meta(host):
    url = f"https://{host}/.well-known/host-meta"
    response = requests.get(url)
    response.raise_for_status()
    root = ET.fromstring(response.content)
    return XRD(root)

import requests
def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    headers = kwargs.pop('headers', {})
    files = kwargs.pop('files', None)

    if method.lower() == "post":
        response = requests.post(url, data=data, timeout=timeout, headers=headers, files=files, *args, **kwargs)
    elif method.lower() == "get":
        response = requests.get(url, params=data, timeout=timeout, headers=headers, *args, **kwargs)
    else:
        raise ValueError(f"Unsupported method: {method}")

    return response
